class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        xor = cnt0 = 0
        for x in nums:
            xor ^= x
            cnt0 += int(x == 0)
        if xor:
            return n
        if cnt0 == n:
            return 0
        return n - 1

class Solution {
public:
    int longestSubsequence(vector<int>& nums) {
        int xor_ = 0, cnt0 = 0;
        int n = nums.size();
        for (int x : nums) {
            xor_ ^= x;
            cnt0 += x == 0 ? 1 : 0;
        }
        if (xor_ != 0) {
            return n;
        }
        return cnt0 == n ? 0 : n - 1;
    }
};

function longestSubsequence(nums: number[]): number {
    let [xor, cnt0] = [0, 0];
    for (const x of nums) {
        xor ^= x;
        cnt0 += x === 0 ? 1 : 0;
    }
    const n = nums.length;
    if (xor) {
        return n;
    }
    if (cnt0 === n) {
        return 0;
    }
    return n - 1;
}

class Solution:
    def removeSubstring(self, s: str, k: int) -> str:
        stk = []
        for c in s:
            if stk and stk[-1][0] == c:
                stk[-1][1] += 1
            else:
                stk.append([c, 1])
            if c == ")" and len(stk) > 1 and stk[-1][1] == k and stk[-2][1] >= k:
                stk.pop()
                stk[-1][1] -= k
                if stk[-1][1] == 0:
                    stk.pop()
        return "".join(c * v for c, v in stk)

class Solution {
public:
    string removeSubstring(string s, int k) {
        vector<pair<char, int>> stk;
        for (char c : s) {
            if (!stk.empty() && stk.back().first == c) {
                stk.back().second += 1;
            } else {
                stk.emplace_back(c, 1);
            }
            if (c == ')' && stk.size() > 1) {
                auto& top = stk.back();
                auto& prev = stk[stk.size() - 2];
                if (top.second == k && prev.second >= k) {
                    stk.pop_back();
                    prev.second -= k;
                    if (prev.second == 0) {
                        stk.pop_back();
                    }
                }
            }
        }
        string res;
        for (auto& p : stk) {
            res.append(p.second, p.first);
        }
        return res;
    }
};

class Solution:
	def countNoZeroPairs(self, n: int) -> int:
		digits = list(map(int, str(n)))[::-1]
		digits.append(0)  # absorb final carry
		L = len(digits)

		# dp[carry][aliveA][aliveB]
		dp = [[[0] * 2 for _ in range(2)] for _ in range(2)]
		dp[0][1][1] = 1

		for pos in range(L):
			ndp = [[[0] * 2 for _ in range(2)] for _ in range(2)]
			target = digits[pos]
			for carry in range(2):
				for aliveA in range(2):
					for aliveB in range(2):
						ways = dp[carry][aliveA][aliveB]
						if ways == 0:
							continue

						if aliveA:
							A = [(d, 1) for d in range(1, 10)]
							if pos > 0:
								A.append((0, 0))  # end number here
						else:
							A = [(0, 0)]

						if aliveB:
							B = [(d, 1) for d in range(1, 10)]
							if pos > 0:
								B.append((0, 0))
						else:
							B = [(0, 0)]

						for da, na in A:
							for db, nb in B:
								s = da + db + carry
								if s % 10 != target:
									continue
								ndp[s // 10][na][nb] += ways
			dp = ndp

		return dp[0][0][0]

class Solution {
public:
	long long countNoZeroPairs(long long n) {
		std::string s = std::to_string(n);
		int m = (int) s.size();
		std::vector<int> digits(m + 1);
		for (int i = 0; i < m; i++) {
			digits[i] = s[m - 1 - i] - '0';
		}
		digits[m] = 0;

		long long dp[2][2][2] = {};
		dp[0][1][1] = 1;

		for (int pos = 0; pos < m + 1; pos++) {
			long long ndp[2][2][2] = {};
			int target = digits[pos];
			for (int carry = 0; carry <= 1; carry++) {
				for (int aliveA = 0; aliveA <= 1; aliveA++) {
					for (int aliveB = 0; aliveB <= 1; aliveB++) {
						long long ways = dp[carry][aliveA][aliveB];
						if (!ways) continue;
						int aDigits[10];
						int aNext[10];
						int aLen = 0;
						if (aliveA) {
							for (int d = 1; d <= 9; d++) {
								aDigits[aLen] = d;
								aNext[aLen] = 1;
								aLen++;
							}
							if (pos > 0) {
								aDigits[aLen] = 0;
								aNext[aLen] = 0;
								aLen++;
							}
						} else {
							aDigits[0] = 0;
							aNext[0] = 0;
							aLen = 1;
						}

						int bDigits[10];
						int bNext[10];
						int bLen = 0;
						if (aliveB) {
							for (int d = 1; d <= 9; d++) {
								bDigits[bLen] = d;
								bNext[bLen] = 1;
								bLen++;
							}
							if (pos > 0) {
								bDigits[bLen] = 0;
								bNext[bLen] = 0;
								bLen++;
							}
						} else {
							bDigits[0] = 0;
							bNext[0] = 0;
							bLen = 1;
						}

						for (int ia = 0; ia < aLen; ia++) {
							int da = aDigits[ia];
							int na = aNext[ia];
							for (int ib = 0; ib < bLen; ib++) {
								int db = bDigits[ib];
								int nb = bNext[ib];
								int sum = da + db + carry;
								if (sum % 10 != target) continue;
								int ncarry = sum / 10;
								ndp[ncarry][na][nb] += ways;
							}
						}
					}
				}
			}
			std::memcpy(dp, ndp, sizeof(dp));
		}

		return dp[0][0][0];
	}
};

class Solution:
    def maxDistance(self, words: List[str]) -> int:
        n = len(words)
        ans = 0
        for i in range(n):
            if words[i] != words[0]:
                ans = max(ans, i + 1)
            if words[i] != words[-1]:
                ans = max(ans, n - i)
        return ans

class Solution {
